<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesListRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesUidVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVersionVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesItem;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor\PlatformIdentityRolesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the PlatformIdentityRolesAccessor trait.
 *
 * Covers null default, string/VO assignment via withRoles,
 * getRoles/roles accessors, and isRolesChanged with/without original.
 */
class PlatformIdentityRolesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRoles creates a new instance with the Roles set
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromString(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )), $result->getRoles());
    }
    /**
     * Asserts that withroles has access to the value object
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )), $result->roles()->value());
    }
    public function testChangedRoles(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityRolesAccessorUnitTest()->withRoles(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )));
        $original = $holder->withRoles(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )));
        $same = $holder->withRoles(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )));
        $modified = $holder->withRoles(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('other'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('other')),
            PlatformIdentityRolesVersionVO::from(2)
        )));

        // Act
        $withSame = $original->isRolesChanged($same);
        $withDiferent = $original->isRolesChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithPlatformIdentityRolesAccessorUnitTest
{
    use PlatformIdentityRolesAccessor;
}
